<script setup lang="ts">
import type { Task } from '@/lib/api';import Badge from '@/components/ui/Badge.vue';defineProps<{task:Task}>();defineEmits<{retry:[id:number];cancel:[id:number]}>()
</script>
<template><article class="flex flex-col gap-3 rounded-card border border-border bg-surface p-4 sm:flex-row sm:items-center"><div class="min-w-0 flex-1"><div class="flex flex-wrap items-center gap-2"><strong>任务 #{{task.id}}</strong><Badge :tone="task.state==='succeeded'?'good':task.state==='dead_letter'?'bad':task.state==='retry_wait'?'warn':'muted'">{{task.state}}</Badge></div><p class="mt-1 truncate text-xs text-muted">幂等键 {{task.idempotency_key}}</p><p v-if="task.last_error" class="mt-1 text-sm text-status-missing">{{task.last_error}}</p><p v-if="task.next_retry_at" class="mt-1 text-xs text-muted">下次重试：{{new Date(task.next_retry_at).toLocaleString()}}</p></div><div class="flex gap-2"><button v-if="task.state==='dead_letter'||task.state==='retry_wait'" class="min-h-[44px] rounded-md border border-border px-3 text-sm hover:bg-surface-2" @click="$emit('retry',task.id)">提前重试</button><button v-if="task.state==='queued'" class="min-h-[44px] rounded-md border border-border px-3 text-sm hover:bg-surface-2" @click="$emit('cancel',task.id)">取消排队</button></div></article></template>